import logging
from functools import wraps


def add_method_trace(method):
    @wraps(method)
    def wrapper(self, *args, **kwargs):
        self.logger.debug(f"Calling {method.__name__} with args={args} kwargs={kwargs}")
        result = method(self, *args, **kwargs)
        self.logger.debug(f"Method {method.__name__} result={result}")
        return result
    return wrapper


class Config(object):
    def __init__(self, logger=None):
        self.logger = logger or logging
        self.base_config = {
            'ips': [],
            'ueproxy_trials': 5,
            'ueproxy_interval': 3,
            'heartbeat_interval': 2,
            'heartbeat_ip': None
        }

    @add_method_trace
    def _update_ueproxy_config(self, ueproxy_config, key, value, operation='set', condition=None):
        """
        Update the ueproxy_config dictionary based on the specified operation.

        Args:
            ueproxy_config (dict): The dictionary to be updated.
            key (str): The key in the dictionary to be updated.
            value (any): The value to be set, appended, or compared.
            operation (str, optional): The operation to be performed. Defaults to 'set'.
                - 'set': Set the value of the key to the specified value.
                - 'append': Append the value to the list associated with the key, if not already present.
                - 'max': Set the value of the key to the maximum of the current value and the specified value.
                - 'min': Set the value of the key to the minimum of the current value and the specified value.
            condition (bool, optional): The condition that must be satisfied for the update to occur. Defaults to None.
                If None, the update will always occur.

        Returns:
            None
        """
        operations = {
            'set': lambda: value,
            'append': lambda: ueproxy_config[key].append(value) if value not in ueproxy_config[key] else None,
            'max': lambda: max(ueproxy_config.get(key, value), value),
            'min': lambda: min(ueproxy_config.get(key, value), value)
        }
        if condition is None or condition:
            result = operations[operation]()
            if operation != 'append':  # 'append' operation is handled in-place
                ueproxy_config[key] = result

    @add_method_trace
    def _get_launcher_config_from_source(self, source, is_tl=True):
        """
        Retrieves the launcher configuration from the specified source.

        Args:
            source (str): The source from which to retrieve the launcher configuration.
            is_tl (bool, optional): Indicates whether the source is a TL (True) or UTE (False), Defaults to True.

        Returns:
            dict: The launcher configuration.

        Raises:
            ValueError: If the source is invalid or unsupported.
        """
        ueproxy_config = self._initialize_ueproxy_config()
        # Logic for retrieving and updating ueproxy_config based on source
        if is_tl:
            return self._get_launcher_config_from_tl(source, ueproxy_config)
        else:
            return self._get_launcher_config_from_ute(source, ueproxy_config)

    def _get_launcher_config_from_tl(self, tl, ueproxy_config):
        """
        Retrieves the launcher configuration from the Testline.

        Args:
            tl (Testline): The Testline object containing the configuration.
            ueproxy_config (dict): The basic initial launcher configuration.

        Returns:
            dict: The updated launcher configuration as a dictionary.
        """
        for ue in tl.ues:
            # Skip the non-TafUeFastmile UEs
            if not hasattr(ue, 'ue_manage_ip'):
                continue

            ue_ips = {"ue_pc_address": ue.ue_pc_address,
                      "ue_manage_ip": ue.ue_manage_ip,
                      "proxy_mngr_port": ue.proxy_mngr_port
                      }
            self._update_ueproxy_config(ueproxy_config, 'ips', ue_ips, 'append', condition=ue.ue_manage_ip)
            self._update_ueproxy_config(ueproxy_config, 'ueproxy_trials', ue.ueproxy_trials, 'max',
                                        condition=ue.ueproxy_trials is not None)
            self._update_ueproxy_config(ueproxy_config, 'ueproxy_interval', ue.ueproxy_interval, 'max',
                                        condition=ue.ueproxy_interval is not None)

            if self._is_receiver(ue.version):
                heartbeat_ip = (ue.data_transfer[0].app_server.bind_interface_ip
                                or ue.data_transfer[0].app_server.address)
                self._update_ueproxy_config(ueproxy_config, 'heartbeat_ip', heartbeat_ip)
                self._update_ueproxy_config(ueproxy_config,
                                            'heartbeat_interval',
                                            ue.heartbeat_interval,
                                            'min',
                                            condition=ue.heartbeat_interval is not None)

        self.logger.info(f"ueproxy config from taf.config.testline configuration: {ueproxy_config}")
        return ueproxy_config

    def _get_launcher_config_from_ute(self, inline_config, ueproxy_config): # noqa
        """
        Retrieves the launcher configuration from the UTE (Unified Test Environment).

        Args:
            inline_config (dict): A dictionary containing the inline configuration.
            ueproxy_config (dict): The basic initial launcher configuration.

        Returns:
            dict: The launcher configuration retrieved from the UTE.
        """
        for value in inline_config.values():
            constructor_params = value['CONSTRUCTOR_PARAMETERS']
            configuration_params = constructor_params['configuration']
            app_server_params = configuration_params['data_transfer']['iperf']['app_server']
            if 'ue_manage_ip' not in constructor_params:
                continue

            ue_ips = {"ue_pc_address": configuration_params.get('ue_pc_address'),
                      "ue_manage_ip": constructor_params.get('ue_manage_ip'),
                      "proxy_mngr_port": configuration_params.get('proxy_mngr_port')
                      }
            self._update_ueproxy_config(ueproxy_config, 'ips', ue_ips, 'append')

            if self._is_receiver(constructor_params['version']):
                heartbeat_ip = app_server_params.get('bind_interface_ip') or app_server_params.get('address')
                if heartbeat_ip:
                    self._update_ueproxy_config(ueproxy_config, 'heartbeat_ip', heartbeat_ip)

                heartbeat_interval = constructor_params.get('heartbeat_interval')
                if heartbeat_interval:
                    self._update_ueproxy_config(ueproxy_config,
                                                'heartbeat_interval',
                                                heartbeat_interval,
                                                'min',
                                                condition=heartbeat_interval is not None)

            ueproxy_trials = constructor_params.get('ueproxy_trials')
            if ueproxy_trials is not None:
                self._update_ueproxy_config(ueproxy_config, 'ueproxy_trials', ueproxy_trials, 'max')

            ueproxy_interval = constructor_params.get('ueproxy_interval')
            if ueproxy_interval is not None:
                self._update_ueproxy_config(ueproxy_config, 'ueproxy_interval', ueproxy_interval, 'max')

        self.logger.info(f"ueproxy config from ute_ue: {ueproxy_config}")
        return ueproxy_config

    @staticmethod
    def _is_receiver(version):
        """
        Checks if the given version is a receiver.

        Args:
            version: The version to check.

        Returns:
            True if the version is a receiver, False otherwise.
        """
        return version and 'receiver' in str(version).lower()

    def _initialize_ueproxy_config(self):
        """
        Initializes the configuration for the UE Proxy Manager.

        Returns:
            dict: The base configuration for the UE Proxy Manager, with default values for various parameters.
        """
        return self.base_config.copy()

    def get_config(self, config):
        """
        Retrieves the launcher configuration based on the input `config` parameter.

        Args:
            config (dict or object): The configuration object to retrieve the launcher configuration from.

        Returns:
            dict: The launcher configuration.

        Raises:
            ValueError: If the `config` parameter is not of type dict or object with 'ues' attribute.

        """
        if isinstance(config, dict):
            return self._get_launcher_config_from_source(config, is_tl=False)
        elif hasattr(config, 'ues'):
            return self._get_launcher_config_from_source(config, is_tl=True)
        else:
            raise ValueError("Invalid config type. Expected dict or object with 'ues' attribute.")
